import json, sqlite3
from pathlib import Path
import pandas as pd
import numpy as np
ROOT=Path(__file__).parent; RAW=ROOT/'data/raw'; CLEAN=ROOT/'data/clean'; OUT=ROOT/'outputs'; SQL=ROOT/'sql/queries.sql'
CLEAN.mkdir(parents=True,exist_ok=True); OUT.mkdir(exist_ok=True); SQL.parent.mkdir(exist_ok=True)
cust_raw=pd.read_csv(RAW/'customers.csv',dtype={'age':'string'}); prod=pd.read_csv(RAW/'products.csv'); raw=pd.read_csv(RAW/'orders.csv'); tickets=pd.read_csv(RAW/'tickets.csv',keep_default_na=False)
audit={}
for n,d in [('customers',cust_raw),('products',prod),('orders',raw),('tickets',tickets)]: audit[n]={'shape':list(d.shape),'dtypes':{c:str(t) for c,t in d.dtypes.items()},'missing':{c:{'count':int(d[c].isna().sum()),'pct':round(float(d[c].isna().mean()*100),2)} for c in d}}
audit['orders_specific']={'rows':len(raw),'exact_duplicates':int(raw.duplicated().sum()),'pending':int(raw.status.eq('pending').sum()),'distinct_order_id':int(raw.order_id.nunique()),'bad_amount':int(pd.to_numeric(raw.order_amount,errors='coerce').isna().sum()),'negative_delivery':int(pd.to_numeric(raw.delivery_minutes,errors='coerce').lt(0).sum()),'blank_delivery':int((raw.delivery_minutes.isna()|raw.delivery_minutes.astype(str).str.strip().eq('')).sum())}
audit['customers_specific']={'blank_age':int((cust_raw.age.isna()|cust_raw.age.astype(str).str.strip().eq('')).sum()),'age_outside_10_100':int(((pd.to_numeric(cust_raw.age,errors='coerce')<10)|(pd.to_numeric(cust_raw.age,errors='coerce')>100)).sum()),'city_spellings':int(cust_raw.city.nunique()),'gender_spellings_nonblank':int(cust_raw.loc[cust_raw.gender.astype(str).str.strip().ne(''),'gender'].nunique()),'blank_gender':int((cust_raw.gender.isna()|cust_raw.gender.astype(str).str.strip().eq('')).sum())}
c=cust_raw.copy(); c['city']=c.city.astype(str).str.strip().str.title(); g=c.gender.fillna('').astype(str).str.strip().str.lower(); c['gender']=g.map({'m':'male','male':'male','f':'female','female':'female'}).fillna('unknown'); c['age']=pd.to_numeric(c.age,errors='coerce').astype(float); c.loc[~c.age.between(10,100),'age']=np.nan; c['age']=c.age.fillna(c.groupby('city').age.transform('median')).round().astype(int); c['signup_date']=pd.to_datetime(c.signup_date).dt.strftime('%Y-%m-%d'); c=c[['customer_id','city','signup_date','age','gender']]
p=prod.copy(); p['price_inr']=pd.to_numeric(p.price_inr)
o=raw.drop_duplicates().copy(); o['order_ts']=pd.to_datetime(o.order_ts); o=o.sort_values(['order_id','order_ts']).drop_duplicates('order_id',keep='last').copy()
for col in ['order_amount','quantity','discount_pct','delivery_minutes']: o[col]=pd.to_numeric(o[col],errors='coerce')
o=o.merge(p[['product_id','category','price_inr']],on='product_id',how='left',validate='many_to_one'); o['order_amount']=o.order_amount.fillna((o.price_inr*o.quantity*(1-o.discount_pct/100)).round(2)).round(2); o.loc[o.delivery_minutes<0,'delivery_minutes']=np.nan
m=o.status.eq('completed'); cat_med=o.loc[m].groupby('category').delivery_minutes.transform('median'); o.loc[m,'delivery_minutes']=o.loc[m,'delivery_minutes'].fillna(cat_med); o['order_ts']=o.order_ts.dt.strftime('%Y-%m-%d %H:%M:%S'); o=o[['order_id','customer_id','product_id','order_ts','quantity','discount_pct','order_amount','delivery_minutes','status','category','price_inr']]
c.to_csv(CLEAN/'customers.csv',index=False); p.to_csv(CLEAN/'products.csv',index=False); o.to_csv(CLEAN/'orders.csv',index=False)
with sqlite3.connect(ROOT/'data/instamart.db') as con:
 for n,d in [('customers',c),('products',p),('orders',o)]: d.to_sql(n,con,if_exists='replace',index=False)
queries='''-- Q1 WHERE then HAVING\nSELECT customer_id,SUM(order_amount) total FROM orders WHERE status='completed' AND order_amount>500 GROUP BY customer_id HAVING SUM(order_amount)>8000;\n-- Q2 three-table join\nSELECT c.city,p.category,SUM(o.order_amount) revenue FROM orders o JOIN customers c USING(customer_id) JOIN products p USING(product_id) WHERE o.status='completed' GROUP BY c.city,p.category ORDER BY c.city,p.category;\n-- Q3 scalar subquery\nSELECT product_id,product_name,price_inr FROM products WHERE price_inr>(SELECT AVG(price_inr) FROM products);\n-- Q4 LEFT JOIN\nSELECT c.customer_id FROM customers c LEFT JOIN orders o ON c.customer_id=o.customer_id AND o.status='completed' WHERE o.order_id IS NULL;\n-- Q5 two CTEs\nWITH spend AS (SELECT customer_id,SUM(order_amount) total FROM orders WHERE status='completed' GROUP BY customer_id), avg_spend AS (SELECT AVG(total) avg_total FROM spend) SELECT spend.customer_id,total FROM spend,avg_spend WHERE total>avg_total;\n-- Q6 ranking windows\nWITH spend AS (SELECT c.city,o.customer_id,SUM(o.order_amount) total FROM orders o JOIN customers c USING(customer_id) WHERE o.status='completed' GROUP BY c.city,o.customer_id) SELECT city,customer_id,total,RANK() OVER(PARTITION BY city ORDER BY total DESC) rnk,DENSE_RANK() OVER(PARTITION BY city ORDER BY total DESC) dense_rnk,ROW_NUMBER() OVER(PARTITION BY city ORDER BY total DESC,customer_id) row_num FROM spend;\n-- Q7 running total\nWITH daily AS (SELECT substr(order_ts,1,10) day,SUM(order_amount) revenue FROM orders WHERE status='completed' GROUP BY substr(order_ts,1,10)) SELECT day,revenue,SUM(revenue) OVER(ORDER BY day) cumulative_revenue FROM daily;'''
SQL.write_text(queries,encoding='utf-8')
with sqlite3.connect(ROOT/'data/instamart.db') as con:
 q=[]
 for stmt in queries.split(';'):
  stmt='\n'.join(x for x in stmt.splitlines() if not x.lstrip().startswith('--')).strip()
  if stmt:q.append(pd.read_sql_query(stmt,con))
completed=o[o.status.eq('completed')].merge(c[['customer_id','city']],on='customer_id'); x=completed.order_amount; q1,q3=x.quantile([.25,.75]); iqr=q3-q1
metrics={'audit':audit,'city_counts':c.city.value_counts().to_dict(),'gender_counts':c.gender.value_counts().to_dict(),'order_rows':len(o),'status_counts':o.status.value_counts().to_dict(),'completed_sum':round(x.sum(),2),'q_counts':[len(z) for z in q],'q2_sum':round(float(q[1].revenue.sum()),2),'q2_largest':q[1].sort_values('revenue').iloc[-1].to_dict(),'q5_mean':round(float(completed.groupby('customer_id').order_amount.sum().mean()),2),'q6_rank_diff':int((q[5].rnk!=q[5].row_num).sum()),'q7_days':len(q[6]),'q7_last':round(float(q[6].cumulative_revenue.iloc[-1]),2),'amount':{'mean':round(x.mean(),2),'median':round(x.median(),2),'skew':round(x.skew(),2),'q1':round(q1,2),'q3':round(q3,2),'lower_fence':round(q1-1.5*iqr,2),'upper_fence':round(q3+1.5*iqr,2),'below':int((x<q1-1.5*iqr).sum()),'above':int((x>q3+1.5*iqr).sum())}}
metrics['city_completed']=completed.groupby('city').order_amount.agg(['sum','mean','count']).round(2).to_dict('index'); metrics['corr']=completed[['order_amount','discount_pct','quantity','delivery_minutes']].corr().round(3).to_dict()
pivot=pd.pivot_table(completed,values='order_amount',index='city',columns='category',aggfunc='sum',margins=True,fill_value=0); metrics['pandas_pivot_total']=round(float(pivot.loc['All','All']),2); metrics['q6_city_leaders']=q[5][q[5].rnk.eq(1)][['city','customer_id','total']].to_dict('records')
(OUT/'part_a_metrics.json').write_text(json.dumps(metrics,indent=2,default=str),encoding='utf-8')
checks=[len(c)==1200,c.city.nunique()==6,c.age.notna().all(),len(o)==12309,o.order_id.nunique()==12309,o.status.value_counts().to_dict()=={'completed':11110,'cancelled':1199},o.order_amount.notna().all(),o.loc[o.status.eq('completed'),'delivery_minutes'].notna().all(),round(x.sum(),2)==2998668.80,o.loc[o.status.eq('cancelled'),'delivery_minutes'].isna().all()]
assert all(checks),metrics
print('ALL CHECKPOINTS PASSED')